
(function(){
const ROUTES={"1":"","2":"","3":"","4":"","5":"","6":"","7":"","8":""};
let selected='1';
function sync(){
 const title=document.getElementById('lineScheduleName');
 const match=(title?.textContent||'').match(/(?:Línea|LÍNEA)\s*(\d+)/i);
 const active=document.querySelector('.lineScheduleChoice.active[data-line-schedule]');
 const n=(match&&match[1])||(active&&active.dataset.lineSchedule)||selected;
 selected=String(n).replace(/hp$/i,'');if(!ROUTES[selected])selected='1';
 document.body.dataset.pdfLine=selected;
 const a=document.getElementById('lineOfficialPdfBtn'),b=document.getElementById('lineRoutePdfNew');
 if(a)a.textContent='📄 HORARIOS LÍNEA '+selected;
 if(b)b.textContent='📍 RECORRIDO LÍNEA '+selected;
}
document.addEventListener('click',function(e){
 const pick=e.target.closest('[data-line-schedule]');
 if(pick){selected=pick.dataset.lineSchedule.replace(/hp$/i,'');sync();}
 if(e.target.closest('#lineRoutePdfNew')){
  sync();const b64=ROUTES[selected];if(!b64){alert('Recorrido no disponible');return;}
  try{const bin=atob(b64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
   const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
   // Android/Chrome abriendo el HTML desde content:// bloquea a veces window.open(blob:).
   // Igual que en las versiones que funcionaban: abrir el PDF en la MISMA pestaña.
   // No revocamos la URL antes de navegar para evitar que el visor reciba un blob inválido.
   window.location.href=url+'#zoom=page-width';
  }catch(err){alert('No se pudo abrir el recorrido PDF.');}
 }
},true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync);else sync();
})();
